def _c1():
    sol = solveset(x**2 - 3*x - 10 < 0, x, S.Reals)
    return len(int_points(lambda k: sol.contains(k) == True))

def _c2():
    k = Symbol('k', integer=True)
    sols = [v for v in range(-200, 201) if v != 1 and Rational(12, v - 1).is_integer and Rational(12, v - 1) > 0]
    return FiniteSet(*sols)

def _c3():
    e = frozenset()
    s = e
    for _ in range(3):
        s = frozenset(subsets(s))
    return len(s)

def _c5():
    S7 = frozenset(range(7))
    return sum(1 for s in subsets(S7) if s and s != S7)

def _c7():
    Uu = FiniteSet(*range(1, 11))
    P = FiniteSet(*[k for k in range(1, 11) if k % 2 == 0])
    Q = FiniteSet(*[k for k in range(1, 11) if isprime(k)])
    return Complement(Uu, Union(P, Q))

def _c8():
    P = int_points(lambda k: k**2 <= 9, -20, 20)
    Q = int_points(lambda k: 0 <= k <= 5, -20, 20)
    return Union(Complement(P, Q), Complement(Q, P))

def _c11():
    return identity_index(lambda U, P, Q: (P | Q) & (P | (U - Q)),
                          [lambda U, P, Q: P, lambda U, P, Q: U,
                           lambda U, P, Q: frozenset(), lambda U, P, Q: P | Q])

def _c12():
    N = 10000
    pct = Rational(65, 100) + Rational(40, 100) - Rational(20, 100)
    return N * (1 - pct)

def _c17():
    vals = [k for k in range(0, 61) if 42 - k >= 0 and 35 - k >= 0 and 60 - (77 - k) >= 0]
    return max(vals) - min(vals)

def _c18():
    s1 = always(lambda U, P, Q, R: P - (Q | R) == (P - Q) & (P - R), 3)
    s2 = always(lambda U, P, Q, R: P - (Q & R) == (P - Q) & (P - R), 3)
    return (s1, s2)

def _c19():
    S = list(range(1, 11))
    return sum(1 for m in range(1 << 10) if any((m >> (k - 1)) & 1 and k % 2 == 1 for k in S))

def _c20():
    pw = lambda S: frozenset(subsets(S))
    s1 = always(lambda U, X, Y: pw(X) | pw(Y) == pw(X | Y), 2)
    s2 = always(lambda U, X, Y: pw(X) & pw(Y) == pw(X & Y), 2)
    return (s1, s2)

def _c21():
    nI = log(4, 2)
    return 2**(5 + 4 - nI)

def _c22():
    P = solveset(x**2 - 5*Abs(x) + 6, x, S.Reals)
    Q = solveset(x**2 - x - 6 <= 0, x, S.Reals)
    return Intersection(P, Q)

def _c23():
    P = Interval.Ropen(-2, 3)
    Q = Interval.Lopen(1, 5)
    return Complement(P, Q)

def _c24():
    return identity_index(lambda U, P, Q: (P & (U - Q)) | ((U - P) & (U - Q)) | (P & Q),
                          [lambda U, P, Q: P | (U - Q), lambda U, P, Q: P & (U - Q),
                           lambda U, P, Q: U, lambda U, P, Q: U - Q])

def _c26():
    vals = set()
    for k in range(0, 11):
        vals.add(10 + 15 - k)
    return len(vals)

def _c27():
    S = subsets(range(1, 5))
    return sum(1 for P in S for Q in S if P <= Q)

def _c28():
    s1 = always(lambda U, P, Q, R: not ((P & Q) == (P & R) and (P | Q) == (P | R)) or Q == R, 3)
    s2 = always(lambda U, P, Q: (P <= Q) == (len(P & (U - Q)) == 0), 2)
    return (s1, s2)

def _c29():
    nPc, nQc, nNone, N = 25, 30, 10, 60
    nP, nQ = N - nPc, N - nQc
    return nP + nQ - (N - nNone)

def _c30():
    S = subsets(range(1, 6))
    return sum(1 for P in S for Q in S if P & Q == frozenset({2}) and P | Q == frozenset({1, 2, 3, 4}))

def _c31():
    sets = [FiniteSet(*range(n, 3*n + 1)) for n in range(4, 10)]
    return len(Intersection(*sets))

def _c33():
    P = {(s[x], s[y]) for s in solve([x**2 + y**2 - 25, y - x**2 + 5], [x, y], dict=True)}
    return len(P)

def _c35():
    n = Symbol('n', positive=True, integer=True)
    nn = int(solve(n*(n - 1)/2 - 28, n)[0])
    return Integer(sum(1 for s in subsets(range(nn)) if 3 <= len(s) <= 6))

def _c37():
    from math import prod
    return Integer(sum(1 for s in subsets(range(1, 13)) if s and prod(s) % 6 == 0))

def _c40():
    ok = [k for k in range(0, 81) if 50 - k >= 0 and 45 - k >= 0 and 0 <= 80 - (95 - k) <= 10]
    return len(ok)

def _c41():
    S = subsets(range(1, 5))
    return sum(1 for P in S for Q in S if len(P & Q) == 1)

def _c44():
    best = max(28 + 32 - 2*k for k in range(0, 29) if 50 - (60 - k) >= 0)
    return best

def _c45():
    return identity_index(lambda U, P, Q, R: (P - Q) | (Q - R) | (R - P),
                          [lambda U, P, Q, R: (P | Q | R) - (P & Q & R),
                           lambda U, P, Q, R: P | Q | R,
                           lambda U, P, Q, R: (P | Q | R) - ((P & Q) | (Q & R) | (R & P)),
                           lambda U, P, Q, R: U - (P & Q & R)], nsets=3)

def _c46():
    for t in range(45, -1, -1):
        rest = 155 - 100 - 2*t          # pq + qr + pr forced by the total of 100
        if rest < 0:
            continue
        for pq in range(rest + 1):
            for qr in range(rest - pq + 1):
                pr = rest - pq - qr
                a = 60 - t - pq - pr; b = 50 - t - pq - qr; c = 45 - t - qr - pr
                if min(a, b, c) >= 0 and a + b + c + pq + qr + pr + t == 100:
                    return t

def _c47():
    S = subsets(range(1, 6))
    return sum(1 for P in S for Q in S if P <= Q and len(Q) - len(P) == 2)

def _c001():
    X, Y = range(3), range(4)
    return Integer(sum(1 for _ in _rels(X, Y)))

def _c002():
    given = [(1, u), (2, v), (3, u)]
    X = {a for a, _ in given}; Y = {b for _, b in given}
    assert len(X) * len(Y) == 6          # so X and Y are exactly these sets
    XY = {(a, b) for a in X for b in Y}
    cands = [(1, v), (u, 1), (4, v), (v, v)]
    inside = [c for c in cands if c in XY]
    assert len(inside) == 1
    return inside[0]

def _c003():
    k = [s for s in solve(Symbol('k')**2 - 9) if s > 0][0]
    X = {-1, 0, 1}
    assert len(X) == k
    return Integer(sum(1 for a, b in _pairs(X) if a * b == 0))

def _c004():
    X = range(1, 11)
    R = {(x, y) for x in X for y in X if y == 2*x - 1}
    return FiniteSet(*[y for _, y in R])

def _c005():
    X = [1, 2, 3]
    return Integer(sum(1 for R in _rels(X) if (1, 2) in R and (2, 1) in R and (3, 3) not in R))

def _c007():
    X = [x for x in range(-5, 6) if abs(x) <= 2]
    return Integer(sum(1 for a, b in _pairs(X) if a**2 + b**2 <= 4))

def _c009():
    x, y = symbols('x y', integer=True, positive=True)
    R = [(a, b) for a in range(1, 16) for b in range(1, 16) if a + 2*b == 15]
    Rinv = [(b, a) for a, b in R]
    return FiniteSet(*[p for p, _ in Rinv])

def _c010():
    X, Y = [1, 2, 3, 4], ['a', 'b']
    return Integer(sum(1 for R in _rels(X, Y)
                       if {p for p, _ in R} == set(X) and {s for _, s in R} == set(Y)))

def _c012():
    P, Q, S = {1, 2}, {3, 4}, {4, 5}
    return Integer(len(set(_pairs(P, Q)) & set(_pairs(P, S))))

def _c013():
    X = [1, 2, 3]
    return Integer(sum(1 for R in _rels(X) if {a for a, _ in R} == {1}))

def _c016():
    X = [1, 2, 3, 4]
    return Integer(sum(1 for R in _rels(X) if _ref(R, X)))

def _c017():
    X = range(1, 16)
    return FiniteSet(*[b for b in X if (3 - b) % 4 == 0])

def _c018():
    X = [1, 2, 3]
    return Integer(sum(1 for R in _rels(X) if _eq(R, X)))

def _c019():
    X = [1, 2, 3]
    I_X = frozenset((a, a) for a in X)
    E = frozenset()
    return (_eq(I_X, X), _sym(E) and _tr(E))

def _c021():
    S = [Rational(k, 2) for k in range(-6, 7)]
    R = _rel_on(S, lambda a, b: Abs(a - b) <= 1)
    return _props(R, S)

def _c022():
    X = [1, 2, 3]
    R = frozenset({(1, 2), (2, 3)})
    closure = _trclose(R | {(a, a) for a in X})
    assert _ref(closure, X) and _tr(closure)
    return Integer(len(closure - R))

def _c023():
    X = [1, 2, 3, 4]
    return Integer(sum(1 for R in _rels(X) if _ref(R, X) and _sym(R)))

def _c024():
    X = [1, 2, 3, 4]
    return Integer(sum(1 for p in _partitions(X) if (1, 2) in _rel_of(p)))

def _c025():
    X = range(1, 11)
    R = _rel_on(X, lambda a, b: (a*a - b*b) % 3 == 0)
    assert _eq(R, X)
    return Integer(len(R))

def _c026():
    S = range(1, 13)
    R = _rel_on(S, lambda a, b: b % a == 0)
    return (_ref(R, S) and _tr(R), _sym(R))

def _c027():
    X = [1, 2, 3, 4]
    G = {(1, 2), (2, 3)}
    best = [p for p in _partitions(X) if G <= _rel_of(p)]
    return Integer(min(len(_rel_of(p)) for p in best))

def _c029():
    a, b = symbols('a b', positive=True, integer=True)
    sols = solve([a + b - 6, a**2 + b**2 - 20], [a, b], dict=True)
    return min(min(s[a], s[b]) for s in sols)

def _c030():
    X = range(1, 11)
    return Integer(sum(1 for a in X for b in X if 2 + b == 5 + a))

def _c031():
    X = [1, 2]
    return Integer(sum(1 for R in _rels(X) if _tr(R)))

def _c033():
    X = range(1, 51)
    ds = lambda n: sum(int(c) for c in str(n))
    R = _rel_on(X, lambda a, b: ds(a) == ds(b))
    assert _eq(R, X)
    classes = {frozenset(b for b in X if (a, b) in R) for a in X}
    return Integer(len(classes))

def _c034():
    X = [1, 2, 3, 4]
    return Integer(sum(1 for p in _partitions(X) if len(p) == 2))

def _c035():
    X = [1, 2, 3]
    return Integer(sum(1 for R in _rels(X) if _ref(R, X) and _sym(R) and not _tr(R)))

def _c036():
    X = [1, 2, 3]
    E = [_rel_of(p) for p in _partitions(X)]
    union_ok = all(_eq(R1 | R2, X) for R1 in E for R2 in E)
    inter_ok = all(_eq(R1 & R2, X) for R1 in E for R2 in E)
    return (union_ok, inter_ok)

def _c037():
    S = range(-40, 41)
    R = _rel_on(S, lambda a, b: a*a - 7*a*b + 6*b*b == 0)
    return _props(R, S)

def _c038():
    X = range(1, 13)
    R = _rel_on(X, lambda a, b: (a - b) % 3 == 0)
    S = _rel_on(X, lambda a, b: (a - b) % 4 == 0)
    return Integer(len(R | S))

def _c039():
    X = [1, 2, 3]
    return Integer(sum(1 for R in _rels(X) if _sym(R) and _tr(R) and not _ref(R, X)))

def _c040():
    X = [1, 2, 3]
    return Integer(sum(1 for R in _rels(X) if _ref(R, X) and _tr(R)))

def _c041():
    X = [1, 2, 3]
    return Integer(sum(1 for R in _rels(X)
                       if {(1, 2), (2, 3)} <= R and _ref(R, X) and _tr(R) and not _sym(R)))

def _c042():
    X = [1, 2, 3, 4, 5]
    return Integer(sum(1 for p in _partitions(X) if (1, 2) not in _rel_of(p)))

def _c043():
    X = range(1, 21)
    def is_pow2_ratio(a, b):
        r = Rational(a, b)
        k = log(r, 2)
        return simplify(2**floor(k) - r) == 0
    R = _rel_on(X, is_pow2_ratio)
    assert _eq(R, X)
    return Integer(len(R))

def _c044():
    X = range(1, 7)
    return Integer(sum(1 for p in _partitions(X) if len(_rel_of(p)) == 14))

def _c045():
    S = range(-15, 16)
    R = _rel_on(S, lambda a, b: (a + 2*b) % 3 == 0)
    T = _rel_on(S, lambda a, b: (a + 3*b) % 5 == 0)
    return (not _eq(R, S), _eq(T, S))

def _c047():
    X = [1, 2, 3, 4]
    return Integer(sum(1 for R in _rels(X) if _sym(R) and len(R) == 6))

def _c003():
    allf = list(it.product(range(6), repeat=3))
    return sum(1 for f in allf if len(set(f)) < 6)

def _c005():
    f = Lambda(x, x**2 + 1); g = Lambda(x, 2*x - 3)
    return g(f(2))

def _c006():
    good = [e for e in _c6 if _mono(e, R)]
    return good[0] if len(good) == 1 else None

def _c007():
    n = Symbol('n', integer=True)
    a, b = symbols('a b', integer=True)
    inj = solve(Eq(2*a + 3, 2*b + 3), a) == [b]
    image = {2*k + 3 for k in range(1, 200)}
    onto = all(m in image for m in range(1, 100))
    return (inj, onto)

def _c010():
    u = Symbol('u', real=True)  # u = y^3
    usol = solve(Eq(u + 2, x), u)[0]
    return real_root(usol, 3)

def _c012():
    g = Symbol('g')
    return solve(Eq(2*g + 3, 6*x - 1), g)[0]

def _c014():
    s1 = function_range(x**3, x, R) == R
    s2 = _mono(x**2, Interval(0, oo))
    return (s1, s2)

def _c026():
    inner = solveset(sqrt(4 - x) - 1 >= 0, x, R)
    return Intersection(inner, Interval(-oo, 4))

def _c027():
    g = (x + 1)/(x - 1)
    bad = Union(FiniteSet(1), solveset(Eq(g, 2), x, R))
    return Complement(R, bad)

def _c028():
    f = Lambda(x, 2*x + 3); g = Lambda(x, x**2 - 1)
    p = Poly(f(g(x)) - g(f(x)), x)
    r = solve(p.as_expr(), x)
    return simplify(r[0]*r[1])

def _c032():
    def f(n):
        return n + 1 if n % 2 == 1 else n - 1
    N = 1000
    imgs = [f(n) for n in range(1, N + 1)]
    inj = len(set(imgs)) == len(imgs)
    onto = set(range(1, N)) <= set(imgs)
    return (inj, onto)

def _c033():
    s_ = Symbol('s', real=True)
    back = solve(Eq(2*s_ - 1, t), s_)[0]          # x in terms of t = 2x - 1
    return expand((4*x**2 - 2*x + 3).subs(x, back).subs(t, x))

def _c036():
    v = Integer(3)
    for _ in range(2026):
        v = 1/(1 - v)
    return v

def _c040():
    fs = list(it.product(range(4), repeat=4))
    s1 = sum(1 for f in fs if all(f[f[i]] == f[i] for i in range(4))) == 41
    s2 = sum(1 for f in fs if len({f[f[i]] for i in range(4)}) == 1) == 92
    return (s1, s2)

def _c041():
    cnt = 0
    for kk in range(-10, 11):
        inj, onto = _classify_pieces((kk + 3)*x, (kk - 3)*x, R)
        cnt += int(inj and onto)
    return cnt

def _c044():
    fpw = Piecewise((x + 2, x < 0), (x**2 - 1, True))
    ys = solveset(fpw, x, R)
    total = set()
    for yv in ys:
        total |= set(solveset(Eq(fpw, yv), x, R))
    return len(total)

def _c20():
    w = simplify((1 + I)/(1 - I))
    return next(n for n in range(1, 50) if simplify(w**n - 1) == 0)

def _c23():
    a, b = _A, _B
    w = expand((a + I*b)**3)
    return simplify(re(w)/a + im(w)/b)

def _c26():
    e = expand((1 + I)*(X + I*Y) - (1 - I)*(X - I*Y))
    return simplify(e/(2*I))

def _c27():
    t = symbols('theta', real=True)
    w = (3 + 2*I*sin(t))/(1 - 2*I*sin(t))
    sols = solveset(simplify(re(expand_complex(w))), t, Interval.open(0, pi))
    return FiniteSet(*[s for s in sols if simplify(im(expand_complex(w)).subs(t, s)) != 0])

def _c28():
    a = symbols('a', real=True)
    w = expand((a + 3*I)*(2 - a*I))  # numerator after multiplying by conjugate of 2 + ai
    return FiniteSet(*solve(im(w), a))

def _c29():
    w = expand(1/((1 + 2*I)/(1 - I)))
    return re(w) + im(w)

def _c31():
    p = expand((1 + 2*I)*(3 + 4*I))
    s1 = (p == 3 + 8*I)
    s2 = (expand(1/(2 + 0*I)) == Rational(1, 2))
    return (bool(s1), bool(s2))

def _c32():
    r = [s for s in sqrts(7 - 24*I) if re(s) > 0][0]
    return re(r) - im(r)

def _c42():
    k = symbols('k', real=True)
    return FiniteSet(*[s for s in solve(im(expand((1 + k*I)**3)), k) if s != 0])

def _c43():
    nz = [s for s in zsols(lambda z: conjugate(z) - I*z**2) if s != 0]
    return simplify(prod(nz))

def _c47():
    cnt = 0
    for n in range(1, 101):
        if im(expand(sum(I**k for k in range(1, n + 1)))) == 0:
            cnt += 1
    return cnt

def _c49():
    sols = zsols(lambda z: z**2 - conjugate(z))
    s1 = all(simplify(Abs(s) - 1) == 0 for s in sols if s != 0)
    t = symbols('t', real=True)
    s2 = simplify((I*t)**2 + Abs(I*t)**2) == 0   # every purely imaginary z works
    return (bool(s1), bool(s2))

def _c50():
    a, b = symbols('a b', real=True)
    r2 = a**2 + b**2
    sols = solve([a - b*r2, -b - a*r2], [a, b], dict=True)  # (a,b)^{-1} = (b,a), cleared of r2
    return len([s for s in sols if not (s[a] == 0 and s[b] == 0)])

def _c51():
    # z = x + iy with y != 0; z + conj(z) = 1 gives x = 1/2; then impose Im(z + 1/z) = 0
    x = Rational(1, 2)
    y = symbols('y', real=True, nonzero=True)
    z = x + I*y
    ys = solve(simplify(im(expand_complex(z + 1/z))/y), y)
    vals = {simplify(expand(z.subs(y, s)**2 + conjugate(z.subs(y, s))**2)) for s in ys}
    assert len(vals) == 1
    return vals.pop()

def _c52():
    s = sum(I**(k**2) for k in range(1, 31))
    w = expand(s/(2 - I))
    return simplify(re(w)**2 + im(w)**2)

def _c53():
    w = sqrts(simplify((3 + 4*I)/(3 - 4*I)))
    return w

def _c55():
    a = symbols('a', real=True)
    z = simplify((a + 2*I)/(2 - a*I))
    assert not z.free_symbols
    return expand(sum(z**k for k in range(0, 2026)))

def _c4():
    zz = 1 - I
    return (Abs(zz), arg(zz))

def _c8():
    th = Symbol('t', real=True)
    zz = 3*(cos(th) + I*sin(th))
    return simplify(1/zz)

def _c14():
    w = solve(Symbol('s')**2 + Symbol('s') + 1, Symbol('s'))[0]
    return simplify(expand((1 + w - w**2)*(1 - w + w**2)))

def _c17():
    import random
    rnd = random.Random(3)
    ok1 = True
    for _ in range(30):
        a = rnd.randint(-9, 9) + I*rnd.randint(-9, 9); b = rnd.randint(-9, 9) + I*rnd.randint(-9, 9)
        if N(Abs(a + b)) > N(Abs(a) + Abs(b)) + 1e-12: ok1 = False
    z1, z2 = Integer(1), Integer(2)   # counterexample for II
    ok2 = not (Abs(z1 + z2) == Abs(z1) + Abs(z2) and z1 != z2)
    return (ok1, ok2)

def _c18():
    sols = solve([x**2 + y**2 - 1, msq(1 + Z) - 3], [x, y], dict=True)
    vals = {simplify(Abs(1 - Z.subs(s))) for s in sols}
    assert len(vals) == 1
    return vals.pop()

def _c21():
    lo, hi = ext_on_circle(3 - 4*I, 2, lambda w: w)
    return lo + hi

def _c25():
    num, den = fraction(together(simplify(re(1/Z)) - Rational(1, 2)))
    # den = 2(x^2+y^2) > 0 off the origin, so the region is num > 0
    expr, sgn = expand(num), 1
    a = Poly(expr, x, y).coeff_monomial(x**2)
    if a < 0:
        expr, sgn = -expr, -1
        a = -a
    return (expand(expr/a), sgn)

def _c26():
    num, den = fraction(together(simplify(re((Z - 2*I)/(Z + 2)))))
    return circ(num)

def _c29():
    z1 = cos(2*pi/3) + I*sin(2*pi/3); z2 = I
    s1 = bool(simplify(arg(expand(z1*z2)) - 7*pi/6) == 0)
    samples = [1 + I, -2 + 3*I, -1 - I, 3 - 4*I, 5, 2*I, -3*I]
    s2 = all(simplify(arg(simplify(1/w)) + arg(w)) == 0 for w in samples)
    return (s1, s2)

def _c30():
    z1 = 1 + I*sqrt(3)
    sols = solve([msq(Z) - 9, msq(z1 + Z) - 25], [x, y], dict=True)
    assert len(sols) == 1
    return simplify(Z.subs(sols[0]))

def _c34():
    sols = solve([msq(Z - 1) - 4, msq(Z - 4*I) - 9], [x, y], dict=True)
    return len({(simplify(s[x]), simplify(s[y])) for s in sols})

def _c36():
    s = Symbol('s')
    w = solve(s**2 + s + 1, s)[0]
