        Ps = P.subs(s)
        if simplify(Ps - I2) == zeros(2, 2) or simplify(Ps + I2) == zeros(2, 2):
            continue  # excluded by the stem
        vals_.add(simplify((Ps.adjugate() + 3 * Ps.inv()).det()))
    assert len(vals_) == 1
    return vals_.pop()

